import sys
MOD = 10**9 + 7

def countPalindromicPaths(matrix):
    n, m = len(matrix), len(matrix[0])
    dp = [[[0] * (n + m) for _ in range(m)] for _ in range(n)]
    dp[0][0][0] = 1

    for i in range(n):
        for j in range(m):
            for k in range(n + m - 1):
                if i > 0:
                    dp[i][j][k] += dp[i - 1][j][k]
                if j > 0:
                    dp[i][j][k] += dp[i][j - 1][k]
                dp[i][j][k] %= MOD
                if i + j < n + m - 1:
                    dp[i][j][i + j + 1] += dp[i][j][k]
                    dp[i][j][i + j + 1] %= MOD
                if i + j > 0 and matrix[i][j] == matrix[i + j - (i + j + 1) // 2][i + j // 2]:
                    dp[i][j][i + j] += dp[i][j][k]
                    dp[i][j][k] -= dp[i][j][k]
                    dp[i][j][i +	j] %= MOD

    return dp[n - 1][m - 1][n + m - 1] % MOD

def main():
    import sys
    input = sys.stdin.read().split()
    n, m = int(input[0]), int(input[1])
    matrix = [input[2 + i * m:2 + (i + 1) * m] for i in range(n)]
    print(countPalindromicPaths(matrix))

if __name__ == "__main__":
    main()
